// Posters and validation are generated by default; pass --video to also export MP4.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import sharp from 'sharp';
const dir=path.dirname(fileURLToPath(import.meta.url));
const bundle=path.resolve(process.argv[2]),preview=process.argv.includes('--preview');
const temp=path.join(dir,'temp/rle-engine'),defaultOutput=path.resolve(dir,'../IMAGE/07-SW-Overview');
await fs.mkdir(temp,{recursive:true});
const trace=JSON.parse(await fs.readFile(path.join(dir,'rle-engine-trace.txt'),'utf8'));
const variant=JSON.parse(await fs.readFile(path.join(dir,'rle-engine-variant.txt'),'utf8'));
const lua=v=>Array.isArray(v)?'{'+v.map(lua).join(',')+'}':v&&typeof v==='object'?'{'+Object.entries(v).map(([k,v])=>`${k}=${lua(v)}`).join(',')+'}':JSON.stringify(v);
const {createTMath}=await import(pathToFileURL(path.join(bundle,'client.js')));
const runtime=await createTMath('return tmath.scene {theme="pro_white"}','bootstrap.lua',{
 renderEngine:'cpu',wasmBinary:await fs.readFile(path.join(bundle,'tmath-wasm.wasm')),
});
runtime.font('Pretendard',await fs.readFile(path.join(bundle,'Pretendard.ttf')));
const reports=[];
const rgb=v=>[v&255,(v>>>8)&255,(v>>>16)&255];
const at=(buffer,w,x,y)=>[...buffer.subarray((Math.floor(y)*w+Math.floor(x))*4,(Math.floor(y)*w+Math.floor(x))*4+3)];
const equal=(a,b,label)=>{if(a.some((v,i)=>Math.abs(v-b[i])>1))throw Error(`${label}: ${a}/${b}`);};
try {
 for(const name of (process.argv.includes('--comparison-only')?['rle-comparison']:process.argv.includes('--overview-only')?['api-rle-surface']:['rle-creation','rle-surface'])) {
  const isOverview=name==='api-rle-surface',isComparison=name==='rle-comparison';
  const sourceDir=isOverview?path.resolve(dir,'../../../../../.vscode/SW/CPU-Overview'):dir;
  const output=isOverview?path.join(sourceDir,'posters'):defaultOutput;
  await fs.mkdir(output,{recursive:true});
  const file=isOverview?'sw-overview-api-rle-surface.lua':'sw-'+name+'.lua',source=await fs.readFile(path.join(sourceDir,file),'utf8');
  if(!source.includes('local trace='+lua(trace)))throw Error('Lua source is stale relative to engine trace');
  runtime.loadLua(source,file);
  const [width,height]=runtime.size(),duration=runtime.duration,fps=30,frames=Math.ceil(duration*fps)+1;
  const samples=isComparison?[0,1,4.9,18.6,24.6,duration]:[0,2,5,9,14,Math.min(20,duration),duration];
  const times=preview&&!isOverview&&!isComparison?samples:Array.from({length:frames},(_,i)=>Math.min(i/fps,duration));
  let minClearance=Infinity;const seen=new Set();
  const operationLast=new Map(),denseLast=new Map(),rleReads=new Set();let drawStart=Infinity;
  for(const time of times) {
   const report=runtime.layoutReport(time,4);
   for(const o of report.objects) {
    if(o.type==='text'&&!o.id.startsWith('label_'))throw Error('Unclassified Text '+o.id);
    if(!o.visible||o.type==='group')continue;
    const b=o.paintBounds;
    if(!b||b.width<=0||b.height<=0)throw Error('Invalid visible bounds '+o.id);
    const c=Math.min(b.x,b.y,width-b.x-b.width,height-b.y-b.height);minClearance=Math.min(c,minClearance);
    if(c<4)throw Error('Canvas overflow '+o.id);
    if(o.type==='text')seen.add(o.id);
    if(isOverview&&o.id.startsWith('write_range_'))operationLast.set(Number(o.id.slice('write_range_'.length)),time);
    if(isOverview&&o.id==='label_call_draw')drawStart=Math.min(drawStart,time);
    if(isComparison&&o.id.startsWith('dense_read_'))denseLast.set(Number(o.id.slice(11)),time);
    if(isComparison&&o.id.startsWith('rle_cursor_'))rleReads.add(o.id);
   }
   const texts=report.objects.filter(o=>o.type==='text'&&o.visible);
   for(let i=0;i<texts.length;i++)for(let j=i+1;j<texts.length;j++) {
    const a=texts[i].paintBounds,b=texts[j].paintBounds;
    if(Math.max(a.x-b.x-b.width,b.x-a.x-a.width)<4&&Math.max(a.y-b.y-b.height,b.y-a.y-a.height)<4)
     throw Error(`Text gap ${texts[i].id}/${texts[j].id} at ${time}`);
   }
  }
  const initial=Buffer.from(runtime.render(0,true)),final=Buffer.from(runtime.render(duration,true));
  let checks=0;
  if(isComparison) {
   const minx=Math.min(...trace.spans.map(s=>s.x)),maxx=Math.max(...trace.spans.map(s=>s.x+s.len));
   const miny=Math.min(...trace.spans.map(s=>s.y)),maxy=Math.max(...trace.spans.map(s=>s.y+1));
   const coverage=new Map();trace.spans.forEach(s=>s.writes.forEach((_,j)=>coverage.set(s.offset+j,s.coverage)));
   for(const [i,s] of trace.spans.entries()) {
    const begin=runtime.bounds(`span_${i+1}_begin`,duration),line=runtime.bounds(`span_${i+1}_len`,duration);
    if(Math.abs(begin.x+begin.width/2-(1400+(s.x-minx+.5)*64))>1||Math.abs(line.width-s.len*64)>3)
     throw Error('Comparison span glyph does not match engine record');
   }
   for(let y=miny;y<maxy;y++)for(let x=minx;x<maxx;x++) {
    const v=255-Math.floor((coverage.get(y*trace.stride+x)||0)*195/255);
    equal(at(final,width,200+(x-minx+.5)*64,330+(y-miny+.5)*64),[v,v,v],'Dense coverage input');
   }
   const blend=(v,a)=>[0,8,16,24].reduce((n,shift)=>n+Math.floor(((v>>>shift)&255)*(a+1)/256)*2**shift,0)>>>0;
   const baseline=new Array(trace.pixels.length).fill(trace.background);
   for(let y=miny;y<maxy;y++)for(let x=minx;x<maxx;x++) {
    const index=y*trace.stride+x,c=coverage.get(index)||0;
    if(c)baseline[index]=c===255?trace.color:(blend(trace.color,c)+blend(baseline[index],255-c))>>>0;
   }
   if(baseline.some((v,i)=>v!==trace.pixels[i]))throw Error('Dense comparison model differs from actual engine output');
   if(denseLast.size!==(maxx-minx)*(maxy-miny)||rleReads.size!==trace.spans.length)throw Error('Wrong traversal counts');
   // Independently reconstruct both conceptual action streams, then verify
   // every settled step. A read/decision and a write each occupy one model slot.
   const actions=[[],[]];
   for(let y=miny;y<maxy;y++)for(let x=minx;x<maxx;x++) {
    const index=y*trace.stride+x;
    actions[0].push({kind:'read'});
    if(coverage.has(index))actions[0].push({kind:'write',index});
   }
   for(const span of trace.spans) {
    actions[1].push({kind:'read'});
    for(let j=0;j<span.len;j++)actions[1].push({kind:'write',index:span.offset+j});
   }
   const memory=actions.map(()=>new Array(trace.pixels.length).fill(trace.background));
   const check=(frame,label)=>{
    for(const [lane,base] of [200,1400].entries())for(let y=miny;y<maxy;y++)for(let x=minx;x<maxx;x++) {
     equal(at(frame,width,base+(x-minx+.5)*64,950+(y-miny+.5)*64),rgb(memory[lane][y*trace.stride+x]),label);checks++;
    }
   };
   check(initial,'comparison initial');
   const slots=Math.max(...actions.map(a=>a.length));
   for(let step=0;step<slots;step++) {
    for(let lane=0;lane<2;lane++) {
     const action=actions[lane][step];
     if(action?.kind==='write')memory[lane][action.index]=baseline[action.index];
    }
    const time=1+(step+1)*.24-.02;
    const frame=Buffer.from(runtime.render(time,true));
    check(frame,`independent action step ${step+1}`);
    if(step+1===actions[1].length) {
     if(memory[1].some((v,i)=>v!==baseline[i]))throw Error('RLE completion output incorrect');
     if(!memory[0].some((v,i)=>v!==baseline[i]))throw Error('Dense must still have outstanding writes');
     const objects=runtime.layoutReport(time,4).objects;
     if(!objects.find(o=>o.id==='label_done_2')?.visible||objects.find(o=>o.id==='label_done_1')?.visible)
      throw Error('Independent completion labels incorrect');
    }
   }
   check(final,'comparison final');
   for(const [lane,base] of [200,1400].entries())for(const [i,action] of actions[lane].entries())
    equal(at(final,width,base+(i+.5)*576/slots,175),action.kind==='read'?[207,140,48]:[32,120,220],'Action token');
   console.log(JSON.stringify({comparison:{denseReads:denseLast.size,rleReads:rleReads.size,pixelWrites:coverage.size,actionCounts:actions.map(a=>a.length),modelCompletionSeconds:actions.map(a=>1+a.length*.24),densePayload:(maxx-minx)*(maxy-miny),rlePayload:trace.spans.length*16}}));
  } else if(name==='rle-surface'||isOverview) {
   const [bx,by,cell]=isOverview?[1620,520,40]:[1340,400,52];
   const memory=new Array(trace.stride*trace.h).fill(trace.background);
   let t=.6;
   const check=(frame,label)=>{
    for(let y=0;y<trace.h;y++)for(let x=0;x<trace.stride;x++) {
     equal(at(frame,width,bx+(x+.5)*cell,by+(y+.5)*cell),rgb(memory[y*trace.stride+x]),`${label} cell ${x},${y}`);checks++;
    }
   };
   check(initial,'initial');
   if(isOverview) {
    if(!Number.isFinite(drawStart)||operationLast.size!==trace.spans.length)throw Error('Incomplete overview sequence');
    check(Buffer.from(runtime.render(drawStart-1/fps,true)),'Prepare must not write pixels');
    for(let i=0;i<trace.spans.length;i++)runtime.bounds(`span_${i+1}_length`,drawStart-1/fps);
   }
   for(const [i,s] of trace.spans.entries()) {
    if(i>0&&i%10===0)t+=.2;
    t+=.12+(s.coverage===255?.55:.22)+.18;
    s.writes.forEach((v,j)=>memory[s.offset+j]=v);
    check(Buffer.from(runtime.render(isOverview?operationLast.get(i+1):t+.05,true)),`span ${i}`);
    t+=(s.coverage===255?.35:.15)+.1;
   }
   if(memory.some((v,i)=>v!==trace.pixels[i]))throw Error('Replay does not match actual Canvas bytes');
   check(final,'final');
  } else {
   for(const [i,s] of trace.spans.entries()) {
    const b=runtime.bounds(`span_${i+1}_begin`,duration),line=runtime.bounds(`span_${i+1}_length`,duration);
    if(Math.abs(b.x+b.width/2-(1240+(s.x+.5)*64))>1||Math.abs(line.width-s.len*64)>3)throw Error('begin/len mismatch');
    const v=255-Math.floor(s.coverage*195/255);
    equal(at(final,width,1240+(s.x+.5)*64,370+(s.y+.5)*64),[v,v,v],'actual span coverage');checks++;
   }
  }
  runtime.loadLua(source.replace('local trace='+lua(trace),'local trace='+lua(variant)),'engine-variant.lua');
  const changed=Buffer.from(runtime.render(runtime.duration,true));
  if(name==='rle-surface'||isOverview) {
   const [vx,vy,vc]=isOverview?[1620,520,40]:[1340,400,52];
   for(let y=0;y<variant.h;y++)for(let x=0;x<variant.stride;x++)
    equal(at(changed,width,vx+(x+.5)*vc,vy+(y+.5)*vc),rgb(variant.pixels[y*variant.stride+x]),'Actual engine variant');
  }
  if(isComparison) {
   const mx=Math.min(...variant.spans.map(s=>s.x)),my=Math.min(...variant.spans.map(s=>s.y));
   const ex=Math.max(...variant.spans.map(s=>s.x+s.len)),ey=Math.max(...variant.spans.map(s=>s.y+1));
   for(const base of [200,1400])for(let y=my;y<ey;y++)for(let x=mx;x<ex;x++)
    equal(at(changed,width,base+(x-mx+.5)*64,950+(y-my+.5)*64),rgb(variant.pixels[y*variant.stride+x]),'comparison engine variant');
  }
  let changedPixels=0;
  for(let i=0;i<changed.length;i+=4)if([0,1,2].some(j=>changed[i+j]!==final[i+j]))changedPixels++;
  if(changedPixels<100)throw Error('Engine input variant did not affect scene');
  runtime.loadLua(source,file);
  const result={name,width,height,duration,frames,framesAudited:times.length,textObjects:seen.size,minClearance,checks,changedPixels,engineCanvasMatch:trace.verifiedCanvasMatch};
  reports.push(result);console.log(JSON.stringify(result));
  for(const t of samples)await sharp(Buffer.from(runtime.render(t,true)),{raw:{width,height,channels:4}}).png().toFile(path.join(temp,`${name}-${t.toFixed(2)}.png`));
  await sharp(final,{raw:{width,height,channels:4}}).webp({lossless:true}).toFile(path.join(output,name+'.webp'));
  if (preview || !process.argv.includes('--video')) continue;
  const ff=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','rgba','-video_size',`${width}x${height}`,'-framerate','30','-i','pipe:0','-an','-c:v','libx264','-preset','medium','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',path.join(output,name+'.mp4')],{stdio:['pipe','inherit','inherit']});
  const end=once(ff,'close');
  for(let i=0;i<frames;i++){
   if(!ff.stdin.write(Buffer.from(runtime.render(Math.min(i/fps,duration),true))))await once(ff.stdin,'drain');
   if(i%180===0)console.log(`${name}: ${i}/${frames}`);
  }
  ff.stdin.end();const [code]=await end;if(code!==0)throw Error('ffmpeg failed');
 }
 await fs.writeFile(path.join(temp,(process.argv.includes('--comparison-only')?'comparison-':process.argv.includes('--overview-only')?'overview-':'')+(preview?'preview-review.txt':'review.txt')),JSON.stringify(reports,null,2)+'\nNo additional inline generated-raster review or manual playback.\n');
} finally {runtime.destroy();}
